"use client";

import React, { useEffect } from "react";
import dynamic from "next/dynamic";
const App = dynamic(() => import("App"), { ssr: false });
import EnvDiag from "components/EnvDiag";

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, info: null };
  }
  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }
  componentDidCatch(error, info) {
    try { console.error("RenderError:", error, info); } catch {}
    this.setState({ error, info });
  }
  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: 16, color: '#fff', background: '#0b0b0e' }}>
          <div style={{ maxWidth: 800, margin: '40px auto' }}>
            <h1 style={{ marginBottom: 12 }}>Something went wrong.</h1>
            <p style={{ opacity: 0.85 }}>A client-side error occurred while rendering the app.</p>
            <pre style={{ marginTop: 12, whiteSpace: 'pre-wrap', background: '#14141a', padding: 12, borderRadius: 8, border: '1px solid rgba(255,255,255,0.1)' }}>
              {String(this.state.error?.stack || this.state.error || 'Unknown error')}
            </pre>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

export default function Page() {
  useEffect(() => {
    const onError = (e) => {
      try { console.error("GlobalError:", e?.message || e?.error || e, e?.filename, e?.lineno, e?.colno, e?.error?.stack); } catch {}
    };
    const onRej = (e) => {
      try { console.error("UnhandledRejection:", e?.reason || e); } catch {}
    };
    window.addEventListener('error', onError);
    window.addEventListener('unhandledrejection', onRej);
    return () => {
      window.removeEventListener('error', onError);
      window.removeEventListener('unhandledrejection', onRej);
    };
  }, []);

  return (
    <>
      {/* Render diagnostics outside the error boundary so it still shows if App fails */}
      <EnvDiag />
      <ErrorBoundary>
        <App />
      </ErrorBoundary>
    </>
  );
}
