"use client";
import { useEffect, useMemo, useState } from "react";
import { NEXT_PUBLIC_SUPABASE_URL as BUILD_URL, NEXT_PUBLIC_SUPABASE_ANON_KEY as BUILD_KEY } from "lib/publicEnv";

function mask(val, opts = { head: 6, tail: 4 }) {
  if (!val) return "";
  const s = String(val);
  if (s.length <= opts.head + opts.tail) return s;
  return `${s.slice(0, opts.head)}…${s.slice(-opts.tail)}`;
}

export default function EnvDiag() {
  const [sw, setSw] = useState({ supported: false, registered: false, scope: "" });
  const [queryEnabled, setQueryEnabled] = useState(true);

  // Determine whether to show diagnostics
  useEffect(() => {
    try {
      const usp = new URLSearchParams(window.location.search);
      const q = usp.get("diag");
      if (q === "0") setQueryEnabled(false);
      if (q === "1") setQueryEnabled(true);
    } catch {}
  }, []);

  useEffect(() => {
    if (typeof navigator !== "undefined" && "serviceWorker" in navigator) {
      navigator.serviceWorker.getRegistration().then((reg) => {
        setSw({ supported: true, registered: !!reg, scope: reg?.scope || "" });
      }).catch(() => setSw((s) => ({ ...s, supported: true })));
    }
  }, []);

  const manifestHref = useMemo(() => {
    try {
      const el = document.querySelector('link[rel="manifest"]');
      return el?.getAttribute('href') || '';
    } catch { return ''; }
  }, []);

  const basePathOk = useMemo(() => {
    try { return (window.location.pathname || '').startsWith('/improvhub'); } catch { return false; }
  }, []);

  // Build-time env (inlined by Next)
  const buildUrl = BUILD_URL || '';
  const buildKey = BUILD_KEY || '';
  const buildUrlOk = /^https?:\/\//.test(buildUrl);

  if (!queryEnabled) return null;

  return (
    <div style={{ position: 'fixed', bottom: 12, left: 12, zIndex: 9999, maxWidth: 360 }}>
      <div style={{ background: 'rgba(20,20,26,0.95)', border: '1px solid rgba(255,255,255,0.25)', borderRadius: 8, padding: 12, color: '#fff', fontSize: 12 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
          <div style={{ opacity: 0.9, fontWeight: 600 }}>Env Diagnostics</div>
          <button
            onClick={() => { try { const usp = new URLSearchParams(window.location.search); usp.set('diag','0'); window.location.search = usp.toString(); } catch {} }}
            style={{ background: 'transparent', color: '#fff', border: '1px solid rgba(255,255,255,0.25)', borderRadius: 6, padding: '4px 8px', cursor: 'pointer' }}
          >Hide</button>
        </div>
        <div style={{ lineHeight: 1.35 }}>
          <div><span style={{ opacity: 0.7 }}>Base path ok:</span> {String(basePathOk)}</div>
          <div><span style={{ opacity: 0.7 }}>Manifest href:</span> {manifestHref || '(none)'}</div>
          <div><span style={{ opacity: 0.7 }}>SW:</span> supported={String(sw.supported)} registered={String(sw.registered)} {sw.scope ? `(scope: ${sw.scope})` : ''}</div>
          <div style={{ marginTop: 6, opacity: 0.85, fontWeight: 600 }}>Supabase</div>
          <div><span style={{ opacity: 0.7 }}>Build URL:</span> {buildUrl || '(empty)'} {buildUrl && !buildUrlOk ? '⚠ invalid' : ''}</div>
          <div><span style={{ opacity: 0.7 }}>Build Key:</span> {buildKey ? mask(buildKey) : '(empty)'}</div>
          <div><span style={{ opacity: 0.7 }}>Client URL (effective):</span> {process.env.REACT_APP_SUPABASE_URL || BUILD_URL || '(empty)'} {(() => { const u = (process.env.REACT_APP_SUPABASE_URL || BUILD_URL || ''); return u && !/^https?:\/\//.test(u) ? '⚠ invalid' : ''; })()}</div>
        </div>
      </div>
    </div>
  );
}
